const request = require('supertest');
const app = require('../app');

describe('User API', () => {
  // Health check
  test('GET /health returns 200', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('status', 'ok');
    expect(response.body).toHaveProperty('timestamp');
  });

  // GET users
  test('GET /users returns 200 with user list', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBe(2);
  });

  // POST users - validation tests
  test('POST /users requires name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({});
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Name is required');
  });

  test('POST /users requires name to be a string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Name must be a string');
  });

  test('POST /users creates user with valid data', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Charlie' });
    expect(response.status).toBe(201);
    expect(response.body).toHaveProperty('name', 'Charlie');
    expect(response.body).toHaveProperty('email', 'charlie@example.com');
    expect(response.body).toHaveProperty('id');
  });
});

